
import React, { useEffect, useRef, useState } from 'react';

interface SafeContentRendererProps {
  content: string;
  title?: string;
  className?: string;
}

export const SafeContentRenderer: React.FC<SafeContentRendererProps> = ({ content, title = 'Content', className = '' }) => {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const [height, setHeight] = useState('100px');
  
  // Use a state that definitely syncs with the DOM
  const [isDark, setIsDark] = useState(() => document.documentElement.classList.contains('dark'));

  useEffect(() => {
    // Handler to update state
    const updateTheme = () => {
      const hasDark = document.documentElement.classList.contains('dark');
      setIsDark(hasDark);
    };

    // Initial check in case it changed before hydration/effect
    updateTheme();

    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.type === 'attributes' && mutation.attributeName === 'class') {
          updateTheme();
        }
      });
    });
    
    observer.observe(document.documentElement, { 
      attributes: true, 
      attributeFilter: ['class'] 
    });
    
    return () => observer.disconnect();
  }, []);

  useEffect(() => {
    const doc = iframeRef.current?.contentDocument;
    if (doc) {
      // Define colors
      const themeStyles = isDark ? `
        :root {
          color-scheme: dark;
          --text-primary: #cbd5e1; /* slate-300 */
          --text-headings: #f8fafc; /* slate-50 */
          --bg-code: #1e293b; /* slate-800 */
          --text-code: #e2e8f0; /* slate-200 */
          --link: #818cf8; /* accent-400 */
          --border: #334155; /* slate-700 */
          --blockquote-border: #6366f1; /* accent-500 */
        }
      ` : `
        :root {
          color-scheme: light;
          --text-primary: #334155; /* slate-700 */
          --text-headings: #0f172a; /* slate-900 */
          --bg-code: #f1f5f9; /* slate-100 */
          --text-code: #1e293b; /* slate-800 */
          --link: #4f46e5; /* accent-600 */
          --border: #e2e8f0; /* slate-200 */
           --blockquote-border: #4f46e5; /* accent-600 */
        }
      `;

      const css = `
        ${themeStyles}
        
        html {
          background-color: transparent !important;
        }
        
        body { 
          background-color: transparent !important;
          font-family: 'Inter', system-ui, -apple-system, sans-serif; 
          color: var(--text-primary);
          line-height: 1.6; 
          margin: 0; 
          padding: 8px; 
          overflow-wrap: break-word;
          overflow-y: hidden;
          transition: color 0.3s ease;
        }

        /* Typography */
        h1, h2, h3, h4, h5, h6 { 
          color: var(--text-headings);
          margin-top: 1.5em; 
          margin-bottom: 0.75em; 
          font-weight: 700; 
          line-height: 1.3;
        }
        h1 { font-size: 1.8em; }
        h2 { font-size: 1.5em; }
        h3 { font-size: 1.25em; }

        p { margin-bottom: 1em; }
        
        a { 
          color: var(--link); 
          text-decoration: none; 
          border-bottom: 1px solid transparent;
          transition: border-color 0.2s;
        }
        a:hover { border-bottom-color: var(--link); }

        ul, ol { margin-left: 20px; margin-bottom: 1em; padding-left: 0; }
        li { margin-bottom: 0.5em; }

        /* Media */
        img { 
          max-width: 100%; 
          height: auto; 
          border-radius: 8px; 
          display: block; 
          margin: 1.5em 0;
        }

        /* Code & Pre */
        pre { 
          background: var(--bg-code); 
          color: var(--text-code); 
          padding: 16px; 
          border-radius: 8px; 
          overflow-x: auto; 
          margin: 1.5em 0;
          font-size: 0.9em;
          border: 1px solid var(--border);
        }
        
        code { 
          font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
          background: var(--bg-code); 
          padding: 2px 5px; 
          border-radius: 4px; 
          font-size: 0.9em;
          color: var(--text-code);
        }
        
        pre code { 
          background: transparent; 
          padding: 0; 
          color: inherit;
        }

        /* Quotes */
        blockquote { 
          border-left: 4px solid var(--blockquote-border); 
          padding-left: 16px; 
          margin: 1.5em 0; 
          font-style: italic; 
          opacity: 0.9;
        }
        
        /* Tables */
        table { width: 100%; border-collapse: collapse; margin: 1.5em 0; }
        th, td { border: 1px solid var(--border); padding: 8px 12px; }
        th { font-weight: 600; text-align: left; }

        /* Scrollbar for pre tags */
        ::-webkit-scrollbar { height: 8px; width: 8px; }
        ::-webkit-scrollbar-track { background: transparent; }
        ::-webkit-scrollbar-thumb { background: var(--border); border-radius: 4px; }
      `;

      const htmlContent = `
        <!DOCTYPE html>
        <html lang="en" class="${isDark ? 'dark' : ''}">
          <head>
            <meta charset="utf-8">
            <style>${css}</style>
          </head>
          <body>${content || '<p style="font-style:italic; opacity: 0.6;">No content available.</p>'}</body>
        </html>
      `;

      doc.open();
      doc.write(htmlContent);
      doc.close();

      // Robust Resize Logic to fix "ResizeObserver loop"
      let animationFrameId: number;
      const resizeObserver = new ResizeObserver(() => {
          // Cancel any pending frame to avoid stacking
          if (animationFrameId) cancelAnimationFrame(animationFrameId);
          
          animationFrameId = requestAnimationFrame(() => {
              if (!iframeRef.current || !iframeRef.current.contentDocument) return;
              const body = iframeRef.current.contentDocument.body;
              if (body) {
                  // Add buffer for padding/margins
                  const newHeight = body.scrollHeight + 20;
                  setHeight((prev) => {
                      const prevVal = parseInt(prev, 10);
                      // Use a threshold of 10px to avoid micro-adjustments causing loops
                      if (Math.abs(newHeight - prevVal) > 10) {
                          return `${newHeight}px`;
                      }
                      return prev;
                  });
              }
          });
      });

      if (doc.body) {
        resizeObserver.observe(doc.body);
      }
      
      return () => {
          resizeObserver.disconnect();
          if (animationFrameId) cancelAnimationFrame(animationFrameId);
      };
    }
  }, [content, isDark]);

  return (
    <iframe
      ref={iframeRef}
      title={title}
      className={`w-full block border-none ${className}`}
      style={{ height, transition: 'height 0.2s ease' }}
      sandbox="allow-same-origin allow-scripts allow-popups"
    />
  );
};
